:root {
  --line: #e2e2e6;
  --muted: #6b6b72;
  --accent: #2f6fed;
  --accent-dark: #255fd4;
  --bg: #fafafb;
  --warn: #c0392b;
  --dup: #9a6a00;
}
* { box-sizing: border-box; }
body {
  font-family: -apple-system, system-ui, "Segoe UI", Roboto, sans-serif;
  margin: 0; background: var(--bg); color: #1c1c20;
}
.wrap { max-width: 660px; margin: 0 auto; padding: 40px 20px 90px; }
h1 { font-size: 22px; margin: 0 0 4px; }
.sub { color: var(--muted); font-size: 14px; margin: 0 0 22px; }

/* Save card (SCN-001, SCN-003) */
.card {
  background: #fff; border: 1px solid var(--line);
  border-radius: 12px; padding: 14px; margin-bottom: 8px;
}
.card .row { display: flex; gap: 8px; }
.card input {
  flex: 1; padding: 11px 13px; font-size: 14.5px;
  border: 1px solid var(--line); border-radius: 8px;
}
.card input:focus { outline: none; border-color: var(--accent); }
.card button {
  padding: 0 18px; font-weight: 600; color: #fff;
  background: var(--accent); border: none; border-radius: 8px; cursor: pointer;
}
.card button:hover { background: var(--accent-dark); }
.card .tagline { display: flex; gap: 8px; margin-top: 8px; align-items: center; }
.card .lbl { font-size: 12px; color: var(--muted); white-space: nowrap; }

/* Save-time notice (SCN-006 invalid, SCN-007 duplicate) */
.notice { font-size: 13px; margin: 8px 2px 22px; min-height: 18px; }
.notice.err { color: var(--warn); }
.notice.dup { color: var(--dup); }

/* Search (SCN-002) */
.search { position: relative; margin-bottom: 4px; }
.search input {
  width: 100%; padding: 13px 14px 13px 40px; font-size: 15.5px;
  border: 1px solid var(--line); border-radius: 10px; background: #fff;
}
.search input:focus { outline: none; border-color: var(--accent); }
.search svg { position: absolute; left: 13px; top: 50%; transform: translateY(-50%); }
.search .clear {
  position: absolute; right: 10px; top: 50%; transform: translateY(-50%);
  border: none; background: none; color: #9a9aa2; font-size: 18px;
  cursor: pointer; display: none;
}

.count {
  font-size: 12.5px; color: var(--muted); margin: 12px 0 10px; min-height: 16px;
}

/* List */
ul { list-style: none; padding: 0; margin: 0; }
li {
  display: flex; align-items: flex-start; gap: 12px;
  padding: 14px 4px; border-bottom: 1px solid var(--line);
}
li:first-child { border-top: 1px solid var(--line); }
.favicon {
  width: 22px; height: 22px; flex: none; border-radius: 5px; margin-top: 2px;
  background: #dfe3ea; display: grid; place-items: center;
  font-size: 11px; color: #7a8395; font-weight: 700;
}
.meta { min-width: 0; flex: 1; }
/* SCN-004: single-line truncation for title and address */
.title {
  font-size: 15px; font-weight: 600;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.title a { color: inherit; text-decoration: none; }
.title a:hover { text-decoration: underline; }
.url {
  font-size: 12.5px; color: var(--muted); margin-top: 1px;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.tags { margin-top: 7px; display: flex; flex-wrap: wrap; gap: 6px; }
.tags .t {
  font-size: 11px; font-weight: 600; color: #345; background: #eef2f8;
  border: 1px solid #e0e6ef; padding: 2px 9px; border-radius: 12px; cursor: pointer;
}
.tags .t:hover { background: #e2e9f5; }

mark { background: #fff2a8; border-radius: 2px; padding: 0 1px; }

/* Empty & no-results (SCN-005 + initial empty state) */
.empty {
  color: var(--muted); font-size: 14px; padding: 32px 0; text-align: center;
  border: 1px dashed var(--line); border-radius: 8px;
}

/* Highlight when jumping to an existing entry (SCN-007) */
.flash { animation: flash 1.4s ease; }
@keyframes flash {
  0% { background: #fff7d6; }
  100% { background: transparent; }
}

